using System; using System.Drawing; using System.Drawing.Imaging; public class LogoProcessor { public static void Main() { using (Bitmap img = new Bitmap(" assets/company_logo.png\)) { Bitmap bmp = new Bitmap(img.Width, img.Height); for (int x = 0; x < img.Width; x++) { for (int y = 0; y < img.Height; y++) { Color c = img.GetPixel(x, y); if (c.R > 210 && c.G > 210 && c.B > 210) { bmp.SetPixel(x, y, Color.Transparent); } else { bmp.SetPixel(x, y, c); } } } bmp.Save(\assets/company_logo_clean.png\, ImageFormat.Png); } } }